def trapezium(f, a, b, n):
    h = (b - a) / n
    total = 0.0
    for i in range(n):
        left = a + i * h
        total += h * (f(left) + f(left + h)) / 2
    return total

def n_needed(f, a, b, exact, tol):
    n = 1
    while abs(trapezium(f, a, b, n) - exact) >= tol:
        n *= 2
    return n
